const incoming = $input.first().json;
const body = incoming.body ?? incoming;
const headers = incoming.headers ?? body.headers ?? {};

function flatten(value) {
  if (value == null) return '';
  if (typeof value === 'string') return value.trim();

  if (Array.isArray(value)) {
    return value
      .map((entry, index) => {
        if (typeof entry === 'string') return `${index + 1}. ${entry}`;
        if (entry == null) return '';
        const parts = [
          entry.gap,
          entry.research_gap,
          entry.researchGap,
          entry.description,
          entry.statement,
          entry.text,
          entry.title
        ].filter(Boolean);
        return parts.length ? `${index + 1}. ${parts.join(' - ')}` : JSON.stringify(entry);
      })
      .filter(Boolean)
      .join('\n');
  }

  if (typeof value === 'object') {
    const parts = [
      value.title,
      value.rationale,
      value.gap,
      value.gaps,
      value.researchGap,
      value.research_gap,
      value.description,
      value.statement,
      value.text
    ].filter(Boolean);
    return parts.length ? parts.map(flatten).join('\n') : JSON.stringify(value);
  }

  return String(value).trim();
}

const baselineSource =
  body.baseline ??
  body.researchBaseline ??
  body.semanticBaseline ??
  body.catalystBaseline ??
  body.catalyst_baseline ??
  {};

const title = flatten(
  baselineSource.title ??
  baselineSource.researchTitle ??
  baselineSource.research_title ??
  body.title ??
  body.researchTitle
);

const rationale = flatten(
  baselineSource.rationale ??
  baselineSource.researchRationale ??
  baselineSource.research_rationale ??
  body.rationale
);

const gaps = flatten(
  baselineSource.gaps ??
  baselineSource.gap ??
  baselineSource.researchGaps ??
  baselineSource.reearch_gaps ??
  baselineSource.research_gaps ??
  baselineSource.researchGap ??
  baselineSource.research_gap ??
  body.gaps ??
  body.gap
);

if (!title && !rationale && !gaps) {
  throw new Error('No CATalyst baseline found. Expected body.baseline with title, rationale, and gaps.');
}

let docsSource =
  body.approvedDocuments ??
  body.approved_documents ??
  body.approvedDocs ??
  body.documents ??
  body.sources ??
  body.papers ??
  [];

if (!Array.isArray(docsSource)) docsSource = [];

const parallelTexts =
  body.approvedTexts ??
  body.approved_texts ??
  body.texts ??
  body.documentTexts ??
  [];

if (docsSource.length === 0 && Array.isArray(parallelTexts) && parallelTexts.length) {
  docsSource = parallelTexts.map(t => ({ text: t, approved: true }));
}

function isApprovedDoc(d) {
  // If the payload is explicitly approvedDocuments, treat it as approved.
  if (body.approvedDocuments || body.approved_documents || body.approvedDocs) return true;

  const status = String(d.status ?? d.approvalStatus ?? d.approval_status ?? '').toUpperCase();
  if (d.isApproved === true || d.approved === true || d.humanApproved === true) return true;
  if (status === 'APPROVED' || status === 'VERIFIED') return true;

  const hasApprovalSignal =
    d.isApproved != null || d.approved != null || d.humanApproved != null ||
    d.status != null || d.approvalStatus != null || d.approval_status != null;

  return !hasApprovalSignal;
}

function pickText(d, i) {
  let t = String(
    d.extracted_text ??
    d.extractedText ??
    d.text ??
    d.documentText ??
    d.document_text ??
    d.content ??
    d.fullText ??
    d.full_text ??
    ''
  ).trim();

  if (!t && Array.isArray(parallelTexts) && typeof parallelTexts[i] === 'string') {
    t = String(parallelTexts[i]).trim();
  }

  return t;
}

function cleanMetaValue(value) {
  if (value == null) return null;
  const s = String(value).replace(/\s+/g, ' ').trim();
  return s || null;
}

function isPdfFilename(value) {
  const s = cleanMetaValue(value);
  if (!s) return false;
  return /\.pdf$/i.test(s) || /^[\w.-]+\.pdf$/i.test(s);
}

function normalizeAuthors(value) {
  if (value == null) return [];
  if (Array.isArray(value)) return value.map(v => cleanMetaValue(v)).filter(Boolean);

  const s = cleanMetaValue(value);
  if (!s) return [];

  return s
    .replace(/\s+and\s+/gi, ' & ')
    .split(/\s*;\s*|\s*&\s*/)
    .map(v => cleanMetaValue(v))
    .filter(Boolean);
}

function warningArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.map(v => String(v).trim()).filter(Boolean);
  if (typeof value === 'string') {
    const s = value.trim();
    if (!s) return [];
    try {
      const parsed = JSON.parse(s);
      if (Array.isArray(parsed)) return parsed.map(v => String(v).trim()).filter(Boolean);
    } catch (e) {}
    return s.split(/\s*,\s*|\s*;\s*/).map(v => v.trim()).filter(Boolean);
  }
  return [];
}

function suspiciousAuthor(value) {
  const s = String(value ?? '').replace(/\s+/g, ' ').trim().toLowerCase();
  if (!s) return true;
  const match = s.match(/^[a-z]+/);
  if (!match) return false;
  const firstWord = match[0];
  const badWords = new Set(['article', 'articles', 'unknown', 'author', 'authors', 'source', 'sources', 'paper', 'papers', 'research', 'study', 'studies', 'journal', 'document', 'documents', 'untitled', 'input', 'output', 'abstract', 'introduction', 'conclusion', 'chapter', 'background', 'method', 'results', 'discussion']);
  return badWords.has(firstWord);
}

function pickMeta(d, i) {
  const m = (d && typeof d === 'object') ? (d.metadata ?? d.meta ?? d) : {};
  const filename = cleanMetaValue(d.filename ?? d.fileName ?? d.file_name);

  const rawTitle = cleanMetaValue(
    m.title ??
    m.documentTitle ??
    m.document_title ??
    null
  );

  const titleLooksLikeFilename =
    !rawTitle ||
    isPdfFilename(rawTitle) ||
    (filename && rawTitle.toLowerCase() === filename.toLowerCase());

  const authorsArray = normalizeAuthors(
    m.authors ??
    m.authorList ??
    m.author_list ??
    m.author ??
    null
  );

  const authorDisplay =
    cleanMetaValue(m.authorDisplay ?? m.author_display) ??
    cleanMetaValue(m.author) ??
    (authorsArray.length ? authorsArray.join('; ') : null);

  const yearRaw = cleanMetaValue(m.year ?? m.publicationYear ?? m.publication_year ?? m.date);
  const yearMatch = yearRaw ? yearRaw.match(/\b(19|20)\d{2}\b/) : null;
  const year = yearMatch ? yearMatch[0] : null;

  const warnings = warningArray(m.warnings);

  if (!authorDisplay && authorsArray.length === 0) warnings.push('MISSING_AUTHOR');
  if (suspiciousAuthor(authorDisplay)) warnings.push('SUSPICIOUS_AUTHOR_METADATA');
  if (!year) warnings.push('MISSING_YEAR');
  if (titleLooksLikeFilename) warnings.push('MISSING_TITLE');
  if (titleLooksLikeFilename && filename) warnings.push('TITLE_FALLBACK_FILENAME');
  if (m.metadataReliable === false || m.metadata_reliable === false) warnings.push('LOW_CONFIDENCE_METADATA');

  const title = titleLooksLikeFilename ? null : rawTitle;
  const computedReliable = Boolean(authorDisplay && year && title && !suspiciousAuthor(authorDisplay));
  const metadataReliable = (m.metadataReliable === false || m.metadata_reliable === false) ? false : computedReliable;

  return {
    author: authorDisplay,
    authors: authorsArray,
    authorDisplay,
    year,
    title,
    journal: cleanMetaValue(m.journal ?? m.source ?? m.publication ?? m.containerTitle ?? m.container_title),
    volume: cleanMetaValue(m.volume),
    issue: cleanMetaValue(m.issue),
    pages: cleanMetaValue(m.pages ?? m.pageRange ?? m.page_range),
    doi: cleanMetaValue(m.doi ?? m.DOI),
    url: cleanMetaValue(m.url ?? m.link),
    publisher: cleanMetaValue(m.publisher),
    sourceType: cleanMetaValue(m.sourceType ?? m.source_type),
    filename,
    fallbackLabel: `Source ${i + 1}`,
    metadataReliable,
    warnings: [...new Set(warnings)]
  };
}

function isBadCitationMetadata(meta) {
  if (!meta) return true;
  const warnings = (meta.warnings ?? []).map(w => String(w).toUpperCase());
  const hasBlockingWarning = warnings.some(w => [
    'MISSING_AUTHOR',
    'MISSING_YEAR',
    'MISSING_TITLE',
    'LOW_CONFIDENCE_METADATA',
    'SUSPICIOUS_AUTHOR_METADATA',
    'TITLE_FALLBACK_FILENAME'
  ].includes(w));

  return meta.metadataReliable === false ||
    hasBlockingWarning ||
    !meta.authorDisplay ||
    !meta.year ||
    !meta.title ||
    suspiciousAuthor(meta.authorDisplay ?? meta.author);
}

function firstDefined(...values) {
  return values.find(v => v !== undefined && v !== null && v !== '');
}

function toNumber(value) {
  if (value == null || value === '') return null;
  const n = Number(value);
  if (!Number.isFinite(n)) return null;
  if (n > 0 && n <= 1) return Math.round(n * 100);
  return Math.max(0, Math.min(100, Math.round(n)));
}

function parseFlags(...values) {
  const out = [];
  for (const value of values) {
    if (value == null) continue;
    if (Array.isArray(value)) {
      out.push(...value.map(v => String(v).trim()).filter(Boolean));
      continue;
    }
    if (typeof value === 'string') {
      const s = value.trim();
      if (!s) continue;
      try {
        const parsed = JSON.parse(s);
        if (Array.isArray(parsed)) {
          out.push(...parsed.map(v => String(v).trim()).filter(Boolean));
          continue;
        }
      } catch (e) {}
      out.push(...s.split(/\s*,\s*|\s*;\s*/).map(v => v.trim()).filter(Boolean));
    }
  }
  return [...new Set(out)];
}

function normalizeTier(rawTier) {
  const key = String(rawTier ?? '').toLowerCase().replace(/[^a-z]/g, '');
  if (!key) return null;
  if (key.includes('core')) return 'Core';
  if (key.includes('support')) return 'Supporting';
  if (key.includes('tangent') || key.includes('minimiz')) return 'Tangential';
  if (key.includes('exclude') || key.includes('low')) return 'Excluded';
  return null;
}

function computeRuntimeTier(obj) {
  const insight = obj.insight ?? obj.documentInsight ?? obj.aiInsight ?? {};
  const scores = obj.scores ?? insight.scores ?? {};

  const providedTier = normalizeTier(firstDefined(obj.sourceTier, obj.source_tier, insight.sourceTier, scores.sourceTier));

  const overallScore = toNumber(firstDefined(
    obj.overallScore,
    obj.overall,
    obj.relevancyScore,
    obj.relevanceScore,
    scores.overall,
    scores.overallScore,
    scores.overall_score,
    insight.overallScore,
    insight.overall
  ));

  const recommendationStatus = cleanMetaValue(firstDefined(
    obj.recommendationStatus,
    obj.recommendation_status,
    obj.recommendation,
    insight.recommendationStatus,
    insight.recommendation_status,
    insight.recommendation
  ));

  const relevanceLevel = cleanMetaValue(firstDefined(
    obj.relevanceLevel,
    obj.relevance_level,
    obj.relevance,
    insight.relevanceLevel,
    insight.relevance_level,
    insight.relevance
  ));

  const mismatchFlags = parseFlags(
    obj.mismatchFlags,
    obj.mismatch_flags,
    obj.mismatchFlagsJson,
    obj.mismatch_flags_json,
    insight.mismatchFlags,
    insight.mismatch_flags,
    insight.mismatchFlagsJson,
    insight.mismatch_flags_json
  );

  const weaknessFlags = parseFlags(
    obj.weaknessFlags,
    obj.weakness_flags,
    obj.weaknessFlagsJson,
    obj.weakness_flags_json,
    insight.weaknessFlags,
    insight.weakness_flags,
    insight.weaknessFlagsJson,
    insight.weakness_flags_json
  );

  const recKey = String(recommendationStatus ?? '').toLowerCase();
  const relKey = String(relevanceLevel ?? '').toLowerCase();
  const hasTopicMismatch = mismatchFlags.some(f => String(f).toUpperCase() === 'TOPIC_MISMATCH');

  let tier = providedTier;
  let tierReason = providedTier ? 'Provided by backend runtime tiering.' : 'Computed in n8n from existing score/status fields.';

  if (!tier) {
    if (recKey.includes('recommended') || relKey === 'high' || (overallScore != null && overallScore >= 75)) {
      tier = 'Core';
    } else if (recKey.includes('needs review') || relKey === 'medium' || (overallScore != null && overallScore >= 60)) {
      tier = 'Supporting';
    } else if (overallScore != null && overallScore >= 40) {
      tier = 'Tangential';
    } else {
      tier = 'Tangential';
      tierReason = 'User approved but low or unknown score; included as Tangential.';
    }
  }



  let guidance = cleanMetaValue(obj.sourceUseGuidance ?? obj.source_use_guidance ?? insight.sourceUseGuidance);
  if (!guidance) {
    if (tier === 'Core') guidance = 'Use as main synthesis evidence.';
    else if (tier === 'Supporting') guidance = 'Use cautiously as supporting evidence.';
    else if (tier === 'Tangential') guidance = 'Use only for brief background; do not center or redirect the introduction around this source.';
    else guidance = 'Do not use as synthesis evidence.';
  }

  return { tier, tierReason, guidance, overallScore, recommendationStatus, relevanceLevel, mismatchFlags, weaknessFlags };
}

function pickEvidenceExcerpts(obj) {
  const insight = obj.insight ?? obj.documentInsight ?? obj.aiInsight ?? {};
  const candidates = obj.evidenceExcerpts ?? obj.evidence_excerpts ?? insight.evidenceExcerpts ?? insight.evidence_excerpts ?? [];
  return Array.isArray(candidates) ? candidates : [];
}

const rawDocs = docsSource
  .map((d, i) => (typeof d === 'string') ? { text: d, approved: true } : (d ?? {}))
  .filter(d => isApprovedDoc(d));

const excludedSources = [];
const approvedDocuments = [];
let usableIndex = 0;

function excludedRecord(obj, originalIndex, tierInfo, reason, extra = {}) {
  return {
    originalIndex: originalIndex + 1,
    documentId: obj.documentId ?? obj.document_id ?? obj.id ?? null,
    filename: obj.filename ?? obj.fileName ?? obj.file_name ?? null,
    sourceTier: 'Excluded',
    overallScore: tierInfo?.overallScore ?? null,
    recommendationStatus: tierInfo?.recommendationStatus ?? null,
    relevanceLevel: tierInfo?.relevanceLevel ?? null,
    mismatchFlags: tierInfo?.mismatchFlags ?? [],
    tierReason: reason,
    ...extra
  };
}

rawDocs.forEach((obj, originalIndex) => {
  const tierInfo = computeRuntimeTier(obj);

  if (tierInfo.tier === 'Excluded') {
    excludedSources.push(excludedRecord(obj, originalIndex, tierInfo, tierInfo.tierReason));
    return;
  }

  const text = pickText(obj, originalIndex);
  if (!text) {
    excludedSources.push(excludedRecord(obj, originalIndex, tierInfo, 'Excluded because the approved document has no extractable text.'));
    return;
  }

  const meta = pickMeta(obj, usableIndex);
  if (isBadCitationMetadata(meta)) {
    excludedSources.push(excludedRecord(obj, originalIndex, tierInfo, 'Excluded from synthesis because citation metadata is unreliable and could produce incorrect APA citations.', {
      metadataWarnings: meta.warnings ?? [],
      metadataPreview: {
        authorDisplay: meta.authorDisplay,
        year: meta.year,
        title: meta.title,
        metadataReliable: meta.metadataReliable
      }
    }));
    return;
  }

  usableIndex += 1;
  meta.fallbackLabel = `Source ${usableIndex}`;

  approvedDocuments.push({
    label: 'Doc' + usableIndex,
    originalLabel: obj.label ?? obj.sourceLabel ?? ('OriginalDoc' + (originalIndex + 1)),
    documentId: obj.documentId ?? obj.document_id ?? obj.id ?? null,
    filename: obj.filename ?? obj.fileName ?? obj.file_name ?? null,
    text,
    metadata: meta,
    evidenceExcerpts: pickEvidenceExcerpts(obj),
    sourceTier: tierInfo.tier,
    sourceUseGuidance: tierInfo.guidance,
    tierReason: tierInfo.tierReason,
    overallScore: tierInfo.overallScore,
    recommendationStatus: tierInfo.recommendationStatus,
    relevanceLevel: tierInfo.relevanceLevel,
    mismatchFlags: tierInfo.mismatchFlags,
    weaknessFlags: tierInfo.weaknessFlags,
    requiredForCoverage: ['Core', 'Supporting'].includes(tierInfo.tier)
  });
});

const sessionId =
  body.sessionId ??
  body.session_id ??
  headers['session-id'] ??
  headers['Session-Id'] ??
  headers['SESSION-ID'] ??
  null;

if (approvedDocuments.length === 0) {
  return [{
    json: {
      abortSynthesis: true,
      success: false,
      status: 'VALIDATION_FAILED',
      validationStatus: 'FAILED',
      message: 'No usable approved documents were available for synthesis. Approved documents were excluded because they were low relevance, topic mismatched, missing text, or had unreliable citation metadata.',
      errorMessage: 'No usable approved documents found after backend/n8n source-tier and citation-metadata guardrails.',
      validationFlags: ['NO_USABLE_APPROVED_DOCUMENTS', 'SOURCE_TIER_OR_CITATION_METADATA_GUARDRAIL_FAILED'],
      unsupportedClaimFlags: [],
      metrics: {
        originalApprovedCount: rawDocs.length,
        usableDocumentCount: 0,
        excludedDocumentCount: excludedSources.length
      },
      excludedSources,
      retryRecommended: false,
      meta: {
        sessionId,
        source: 'citewise-n8n-rag-synthesizer-v2.3-backend-only-guardrails'
      }
    }
  }];
}

const requiredSources = approvedDocuments
  .filter(d => d.requiredForCoverage)
  .map(d => d.label);

const optionalSources = approvedDocuments
  .filter(d => !d.requiredForCoverage)
  .map(d => d.label);

const coveragePoolCount = requiredSources.length > 0 ? requiredSources.length : approvedDocuments.length;
const minRequiredSources = Math.max(1, Math.ceil(coveragePoolCount * 0.8));

const defaultSynthesisInstructions =
  'The CATalyst Title, Rationale, and Research Gap are the primary source of truth. ' +
  'Approved documents are supplementary only. Use Core Sources as main evidence, Supporting Sources cautiously, ' +
  'and Tangential Sources only for brief background. Do not let low-relevance approved documents redirect the topic. ' +
  'Use only [DocN] placeholders; deterministic APA citation formatting happens after validation.';

return [{
  json: {
    abortSynthesis: false,
    sessionId,
    baseline: { title, rationale, gaps },
    approvedDocuments,
    usableDocuments: approvedDocuments,
    excludedSources,
    available_sources: approvedDocuments.map(d => d.label),
    required_sources: requiredSources.length ? requiredSources : approvedDocuments.map(d => d.label),
    optional_sources: optionalSources,
    minRequiredSources,
    maxRetries: 3,
    attempt: 1,
    validation_notes: [],
    synthesisInstructions: body.synthesisInstructions ?? body.synthesis_instructions ?? defaultSynthesisInstructions,
    meta: {
      sessionId,
      originalApprovedCount: rawDocs.length,
      usableDocumentCount: approvedDocuments.length,
      excludedDocumentCount: excludedSources.length,
      requiredSourceCount: requiredSources.length,
      optionalSourceCount: optionalSources.length,
      minRequiredSources,
      source: 'citewise-n8n-rag-synthesizer-v2.3-backend-only-guardrails'
    }
  }
}];

const item = $input.first().json;
const baseline = item.baseline ?? {};
const docs = Array.isArray(item.approvedDocuments) ? item.approvedDocuments : [];

if (!docs.length) throw new Error('No usable approved documents to synthesize.');

const PER_DOC_CHAR_CAP = 11000;
const TANGENTIAL_CHAR_CAP = 5000;
const TOTAL_CHAR_CAP = 56000;

const stopwords = new Set([
  'about','above','after','again','against','among','based','because','before','being',
  'below','between','could','during','field','first','found','from','have','having',
  'into','more','most','other','paper','research','result','results','should','study',
  'studies','system','than','their','there','these','this','those','through','using',
  'where','which','while','within','with','would','title','rationale','gaps'
]);

function normalize(s) {
  return String(s ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function keywordsFromBaseline(b) {
  const base = [b.title, b.rationale, b.gaps].filter(Boolean).join(' ');
  return [...new Set(
    normalize(base)
      .split(/\s+/)
      .filter(w => w.length >= 5 && !stopwords.has(w))
  )].slice(0, 80);
}

const baselineKeywords = keywordsFromBaseline(baseline);

function splitToChunks(text) {
  const clean = String(text ?? '').replace(/\r/g, '').trim();
  let chunks = clean
    .split(/\n\s*\n+/)
    .map(p => p.replace(/\s+/g, ' ').trim())
    .filter(p => p.length >= 180);

  if (chunks.length < 6) {
    chunks = [];
    const flat = clean.replace(/\s+/g, ' ').trim();
    const size = 1500;
    const overlap = 220;
    for (let i = 0; i < flat.length; i += (size - overlap)) {
      const part = flat.slice(i, i + size).trim();
      if (part.length >= 180) chunks.push(part);
    }
  }

  return chunks;
}

function chunkScore(chunk, index, evidenceText, tier) {
  const lower = normalize(chunk);
  const hits = baselineKeywords.filter(k => lower.includes(k)).length;

  const synthesisSignal =
    /\b(gap|limitation|limited|lack|absence|challenge|problem|future research|recommendation|understudied|unexplored|need for|however|despite|although)\b/i.test(chunk) ? 5 : 0;

  const methodSignal =
    /\b(method|methodology|framework|model|architecture|algorithm|dataset|evaluation|metric|experiment|prototype|implementation|testing|validation|benchmark)\b/i.test(chunk) ? 4 : 0;

  const introSignal =
    /\b(abstract|introduction|background|rationale|related work|literature review|discussion|conclusion)\b/i.test(chunk) ? 2 : 0;

  const evidenceSignal = evidenceText && normalize(evidenceText).includes(lower.slice(0, Math.min(80, lower.length))) ? 6 : 0;
  const tierBoost = tier === 'Core' ? 4 : tier === 'Supporting' ? 2 : 0;
  const earlySignal = index < 8 ? 1 : 0;

  return hits * 4 + synthesisSignal + methodSignal + introSignal + evidenceSignal + tierBoost + earlySignal;
}

function excerptText(e) {
  if (!e) return '';
  return String(e.quoteText ?? e.text ?? e.evidenceText ?? e.evidence_text ?? '').replace(/\s+/g, ' ').trim();
}

function selectRelevantText(doc, perDocCap) {
  const raw = String(doc.text ?? '').trim();

  const customText = (Array.isArray(doc.customHighlights) ? doc.customHighlights : (Array.isArray(doc.custom_highlights) ? doc.custom_highlights : [])).join(' ');
  const baseEvidenceText = (Array.isArray(doc.evidenceExcerpts) ? doc.evidenceExcerpts : [])
    .map(excerptText)
    .filter(Boolean)
    .join(' ');
  const evidenceText = [customText, baseEvidenceText].filter(Boolean).join(' ');

  if (raw.length <= perDocCap) {
    const prefix = evidenceText ? `Custom Highlights and Emphasized Excerpts:\n${evidenceText}\n\nSelected source text:\n` : '';
    return (prefix + raw.replace(/\s+/g, ' ').trim()).slice(0, perDocCap);
  }

  const chunks = splitToChunks(raw);
  const ranked = chunks
    .map((chunk, index) => ({ chunk, index, score: chunkScore(chunk, index, evidenceText, doc.sourceTier) }))
    .sort((a, b) => b.score - a.score || a.index - b.index);

  const selected = ranked
    .slice(0, doc.sourceTier === 'Tangential' ? 5 : 10)
    .sort((a, b) => a.index - b.index);

  let joined = selected
    .map(x => `[chunk_order=${x.index + 1}; relevance_hint=${x.score}]\n${x.chunk}`)
    .join('\n\n');

  if (evidenceText) {
    joined = `Custom Highlights and Emphasized Excerpts:\n${evidenceText}\n\nSelected source text:\n${joined}`;
  }

  if (joined.length > perDocCap) joined = joined.slice(0, perDocCap);

  return joined;
}

function tierRank(tier) {
  if (tier === 'Core') return 1;
  if (tier === 'Supporting') return 2;
  if (tier === 'Tangential') return 3;
  return 9;
}

let runningTotal = 0;
const contextBlocks = [];
const sourceManifest = [];
const orderedDocs = [...docs].sort((a, b) => tierRank(a.sourceTier) - tierRank(b.sourceTier));

for (const d of orderedDocs) {
  const remaining = TOTAL_CHAR_CAP - runningTotal;
  if (remaining <= 800) break;

  const tier = d.sourceTier ?? 'Supporting';
  const perDocCap = tier === 'Tangential' ? TANGENTIAL_CHAR_CAP : PER_DOC_CHAR_CAP;
  const cap = Math.min(perDocCap, remaining);
  const selectedText = selectRelevantText(d, cap);
  runningTotal += selectedText.length;

  const m = d.metadata ?? {};
  const authors = Array.isArray(m.authors)
    ? m.authors.join('; ')
    : (m.authorDisplay ?? m.author ?? '');
  const metaBits = [];
  if (m.title) metaBits.push('title: ' + m.title);
  if (authors) metaBits.push('authors: ' + authors);
  if (m.year) metaBits.push('year: ' + m.year);
