const draft = $input.first().json;
const prep = $('Prepare RAG Context1').first().json;

const sections = draft.sections ?? {};
const background = String(sections.background ?? '').trim();
const rationale = String(sections.rationale ?? '').trim();
const gap = String(sections.gap ?? '').trim();

const manifest = Array.isArray(prep.source_manifest) ? prep.source_manifest : [];
const allValidLabels = (prep.available_sources ?? manifest.map(s => s.label)).map(x => String(x));
const validLabels = new Set(allValidLabels.map(x => x.toLowerCase()));

const requiredSourceLabelsRaw = Array.isArray(prep.required_sources) && prep.required_sources.length
  ? prep.required_sources.map(x => String(x))
  : manifest.filter(s => s.requiredForCoverage).map(s => String(s.label));

const requiredSourceLabels = requiredSourceLabelsRaw.length ? requiredSourceLabelsRaw : allValidLabels;
const requiredLabelSet = new Set(requiredSourceLabels.map(x => x.toLowerCase()));
const optionalLabelSet = new Set((prep.optional_sources ?? []).map(x => String(x).toLowerCase()));
const totalSources = validLabels.size;
const requiredSourceCount = requiredLabelSet.size;
const minRequiredSources = prep.minRequiredSources ?? Math.max(1, Math.ceil(Math.max(1, requiredSourceCount) * 0.8));

function normalize(s) {
  return String(s ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const text = [background, rationale, gap].filter(Boolean).join(' ');
const validationFlags = [];
const unsupportedClaimFlags = [];

function extractPlaceholders(s) {
  const labels = [];
  const regex = /\[\s*Doc\s*(\d+)\s*\]/gi;
  let m;
  while ((m = regex.exec(String(s ?? ''))) !== null) labels.push('Doc' + m[1]);
  return labels;
}

const placeholders = extractPlaceholders(text);
const usedLabels = [...new Set(placeholders.map(x => x.toLowerCase()))];
const invalidPlaceholders = [...new Set(placeholders.filter(p => !validLabels.has(p.toLowerCase())))];
const uniqueValidUsed = usedLabels.filter(l => validLabels.has(l));
const uniqueRequiredUsed = uniqueValidUsed.filter(l => requiredLabelSet.has(l));
const uniqueOptionalUsed = uniqueValidUsed.filter(l => optionalLabelSet.has(l));

if (!background || background.length < 80) validationFlags.push('BACKGROUND_TOO_SHORT_OR_MISSING');
if (!rationale || rationale.length < 80) validationFlags.push('RATIONALE_TOO_SHORT_OR_MISSING');
if (!gap || gap.length < 80) validationFlags.push('GAP_TOO_SHORT_OR_MISSING');

if (placeholders.length === 0) validationFlags.push('NO_SOURCE_PLACEHOLDERS_USED');
if (invalidPlaceholders.length > 0) validationFlags.push('INVALID_OR_UNAPPROVED_PLACEHOLDER');

const realApaPattern = /\(([A-Z][A-Za-z'’.-]+(?:\s+et al\.)?|[A-Z][A-Za-z'’.-]+(?:\s*&\s*[A-Z][A-Za-z'’.-]+)?)\s*,\s*(?:19|20)\d{2}[a-z]?\)/g;
const realApaMatches = text.match(realApaPattern) ?? [];
if (realApaMatches.length > 0) validationFlags.push('REAL_APA_CITATION_DETECTED_USE_PLACEHOLDERS_ONLY');

const requiredCoverage = requiredSourceCount === 0 ? 0 : uniqueRequiredUsed.length / requiredSourceCount;
const requiredCoveragePercent = Math.round(requiredCoverage * 100);
const unusedRequiredLabels = [...requiredLabelSet]
  .filter(l => !uniqueRequiredUsed.includes(l))
  .map(l => l.replace(/^doc/i, 'Doc'));

if (uniqueRequiredUsed.length < minRequiredSources) validationFlags.push('SOURCE_COVERAGE_BELOW_REQUIRED_POOL');

// If Core/Supporting sources exist, Tangential sources should not dominate citations.
if (requiredSourceCount > 0 && uniqueOptionalUsed.length > uniqueRequiredUsed.length) {
  validationFlags.push('TANGENTIAL_SOURCES_OVERUSED');
}

const stopwords = new Set([
  'about','above','after','again','against','among','based','because','before','being','below','between',
  'could','during','field','first','found','from','have','having','into','more','most','other','paper',
  'research','result','results','should','study','studies','system','than','their','there','these','this',
  'those','through','using','where','which','while','within','with','would','lack','needs','students'
]);

function gapKeywords(s) {
  return [...new Set(
    normalize(s)
      .split(/\s+/)
      .filter(w => w.length >= 5 && !stopwords.has(w))
  )].slice(0, 60);
}

const gapKeys = gapKeywords(prep.baseline?.gaps ?? '');
const gapNorm = normalize(gap);
const matchedGapKeys = gapKeys.filter(k => gapNorm.includes(k));
const gapKeywordCoverage = gapKeys.length === 0 ? 1 : matchedGapKeys.length / gapKeys.length;

const gapCoverageThreshold = gapKeys.length <= 5 ? 0.45 : 0.35;
if (gapKeys.length > 0 && gapKeywordCoverage < gapCoverageThreshold) validationFlags.push('CATALYST_GAP_COVERAGE_TOO_LOW');

function splitSentences(s) {
  return String(s ?? '')
    .replace(/\n+/g, ' ')
    .split(/(?<=[.!?])\s+/)
    .map(x => x.trim())
    .filter(Boolean);
}

const sentences = [
  ...splitSentences(background).map(s => ({ section: 'background', sentence: s })),
  ...splitSentences(rationale).map(s => ({ section: 'rationale', sentence: s })),
  ...splitSentences(gap).map(s => ({ section: 'gap', sentence: s }))
];

let consecutiveMissing = 0;
let maxConsecutiveMissing = 0;
let citedSentenceCount = 0;

for (const entry of sentences) {
  const sentence = entry.sentence;
  const hasCitation = /\[\s*Doc\s*\d+\s*\]/i.test(sentence);
  const substantial = sentence.length >= 70;

  if (hasCitation) {
    citedSentenceCount++;
    consecutiveMissing = 0;
  } else if (substantial) {
    consecutiveMissing++;
    maxConsecutiveMissing = Math.max(maxConsecutiveMissing, consecutiveMissing);
    unsupportedClaimFlags.push({ section: entry.section, sentence });
  }
}

if (maxConsecutiveMissing > 2) validationFlags.push('INSUFFICIENT_CITATION_DENSITY');
if (sentences.length > 0 && citedSentenceCount / sentences.length < 0.55) validationFlags.push('LOW_CITED_SENTENCE_RATIO');

const isValid = validationFlags.length === 0;

const errorParts = [];
if (validationFlags.includes('REAL_APA_CITATION_DETECTED_USE_PLACEHOLDERS_ONLY')) {
  errorParts.push('Real APA-style citations were detected. Use only [DocN] placeholders.');
}
if (validationFlags.includes('INVALID_OR_UNAPPROVED_PLACEHOLDER')) {
  errorParts.push('Invalid placeholders used: ' + invalidPlaceholders.join(', ') + '. Only use: ' + allValidLabels.join(', ') + '.');
}
if (validationFlags.includes('SOURCE_COVERAGE_BELOW_REQUIRED_POOL')) {
  errorParts.push(`Required Core/Supporting source coverage is ${requiredCoveragePercent}%. You must cite at least ${minRequiredSources} unique required source(s). Unused required: ${unusedRequiredLabels.join(', ') || 'none'}.`);
}
if (validationFlags.includes('TANGENTIAL_SOURCES_OVERUSED')) {
  errorParts.push('Tangential sources were used more than Core/Supporting sources. Prioritize Core and Supporting sources; use Tangential sources only briefly.');
}
if (validationFlags.includes('CATALYST_GAP_COVERAGE_TOO_LOW')) {
  errorParts.push(`CATalyst gap coverage is low. Missing or weakly represented gap keywords: ${gapKeys.filter(k => !matchedGapKeys.includes(k)).slice(0, 12).join(', ')}.`);
}
if (validationFlags.includes('INSUFFICIENT_CITATION_DENSITY') || validationFlags.includes('LOW_CITED_SENTENCE_RATIO')) {
  errorParts.push('Citation density is too low. Add [DocN] immediately after each factual claim.');
}
if (validationFlags.some(f => f.endsWith('_TOO_SHORT_OR_MISSING'))) {
  errorParts.push('One or more required sections are missing or too short. Provide complete Background, Rationale, and Research Gap paragraphs.');
}
if (validationFlags.includes('NO_SOURCE_PLACEHOLDERS_USED')) errorParts.push('No [DocN] placeholders were used.');

return [{
  json: {
    isValid,
    status: isValid ? 'VALIDATED' : 'VALIDATION_FAILED',
    errorMessage: isValid ? null : (errorParts.join(' ') || validationFlags.join('; ')),
    sections: { background, rationale, gap },
    rawAiOutput: draft.rawAiOutput ?? '',
    validationFlags,
    unsupportedClaimFlags,
    sourceUsePlan: draft.sourceUsePlan ?? [],
    metrics: {
      totalSources,
      requiredSourceCount,
      optionalSourceCount: optionalLabelSet.size,
      minRequiredSources,
      uniqueValidSourcesUsed: uniqueValidUsed.length,
      uniqueRequiredSourcesUsed: uniqueRequiredUsed.length,
      uniqueOptionalSourcesUsed: uniqueOptionalUsed.length,
      requiredSourceCoverage: requiredCoverage,
      requiredSourceCoveragePercent: requiredCoveragePercent,
      gapKeywordCoverage,
      gapKeywordCoveragePercent: Math.round(gapKeywordCoverage * 100),
      totalSentences: sentences.length,
      citedSentenceCount,
      citedSentenceRatio: sentences.length ? citedSentenceCount / sentences.length : 0,
      invalidPlaceholders
    },
    placeholders: {
      extracted: placeholders,
      uniqueValidUsed: uniqueValidUsed.map(l => l.replace(/^doc/i, 'Doc')),
      uniqueRequiredUsed: uniqueRequiredUsed.map(l => l.replace(/^doc/i, 'Doc')),
      uniqueOptionalUsed: uniqueOptionalUsed.map(l => l.replace(/^doc/i, 'Doc')),
      invalid: invalidPlaceholders,
      unusedRequired: unusedRequiredLabels
    }
  }
}];

// ── Deterministic Citation Engine ─────────────────────────────────────────
// Self-contained: all helper functions defined here.

function uuid() {
  try {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  } catch (e) {}
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

function splitNameList(raw) {
  if (!raw) return [];
  const s = String(raw).replace(/\s+/g, ' ').trim();
  const bySemicolon = s.split(/;\s*/);
  if (bySemicolon.length > 1) return bySemicolon.filter(Boolean);
  const cp = s.split(/,\s*/);
  const out = [];
  if (cp.length > 1) {
    let looksPaired = true;
    for (let i = 0; i < cp.length - 1; i += 2) {
      if (!cp[i] || !cp[i + 1]) { looksPaired = false; break; }
      if (cp[i].trim().split(/\s+/).length > 3) { looksPaired = false; break; }
    }
    if (looksPaired) {
      for (let i = 0; i < cp.length; i += 2) out.push(cp[i] + ', ' + cp[i + 1]);
    } else {
      out.push(s);
    }
  } else {
    out.push(s);
  }
  return out.filter(Boolean);
}

function lastName(author) {
  const a = String(author).trim();
  if (a.includes(',')) return a.split(',')[0].trim();
  const parts = a.split(/\s+/).filter(Boolean);
  return parts.length ? parts[parts.length - 1] : a;
}

function initials(author) {
  const a = String(author).trim();
  let given = '';
  if (a.includes(',')) {
    given = a.split(',').slice(1).join(' ').trim();
  } else {
    const parts = a.split(/\s+/).filter(Boolean);
    given = parts.slice(0, -1).join(' ');
  }
  if (!given) return '';
  return given
    .split(/\s+/)
    .filter(Boolean)
    .map(g => g[0].toUpperCase() + '.')
    .join(' ');
}

function yearOf(meta) {
  if (!meta.year) return '';
  const m = String(meta.year).match(/\d{4}/);
  return m ? m[0] : '';
}

function authorsOf(meta) {
  if (Array.isArray(meta.authors) && meta.authors.length) {
    return meta.authors.map(a => String(a).trim()).filter(Boolean);
  }
  if (meta.authorDisplay) return splitNameList(meta.authorDisplay);
  if (meta.author) return splitNameList(meta.author);
  return [];
}

function safeTitle(meta) {
  const title = String(meta.title ?? '').replace(/\s+/g, ' ').trim();
  if (!title) return '';
  if (/\.pdf$/i.test(title)) return '';
  return title;
}

function suspiciousAuthor(value) {
  const s = String(value ?? '').replace(/\s+/g, ' ').trim().toLowerCase();
  if (!s) return true;
  const match = s.match(/^[a-z]+/);
  if (!match) return false;
  const firstWord = match[0];
  const badWords = new Set(['article', 'articles', 'unknown', 'author', 'authors', 'source', 'sources', 'paper', 'papers', 'research', 'study', 'studies', 'journal', 'document', 'documents', 'untitled', 'input', 'output', 'abstract', 'introduction', 'conclusion', 'chapter', 'background', 'method', 'results', 'discussion']);
  return badWords.has(firstWord);
}

function metadataWarnings(meta) {
  return Array.isArray(meta.warnings) ? meta.warnings : [];
}

function referenceEntry(meta) {
  const authors = authorsOf(meta);
  let authorStr = '';

  if (authors.length) {
    const formatted = authors.map(a => {
      const ln = lastName(a);
      const ini = initials(a);
      return ini ? ln + ', ' + ini : ln;
    });
    if (formatted.length === 1) authorStr = formatted[0];
    else authorStr = formatted.slice(0, -1).join(', ') + ', & ' + formatted[formatted.length - 1];
  }

  const year = yearOf(meta);
  const title = sentenceCaseTitle(meta.title);

  let entry = '';
  if (authorStr) entry += authorStr + ' ';
  entry += '(' + year + '). ' + title + '.';

  if (meta.journal) {
    entry += ' ' + meta.journal;
    if (meta.volume) {
      entry += ', ' + meta.volume;
      if (meta.issue) entry += '(' + meta.issue + ')';
    }
    if (meta.pages) entry += ', ' + meta.pages;
    entry += '.';
  } else if (meta.publisher) {
    entry += ' ' + meta.publisher + '.';
  }

  if (meta.doi) {
    const doi = String(meta.doi).replace(/^https?:\/\/(dx\.)?doi\.org\//i, '');
    entry += ' https://doi.org/' + doi;
  } else if (meta.url) {
    entry += ' ' + meta.url;
  }

  return entry.trim();
}

function citationMetadataUsable(meta) {
  if (!meta) return false;
  const authors = authorsOf(meta);
  const year = yearOf(meta);
  const title = safeTitle(meta);
  const warnings = metadataWarnings(meta);
  const blockingWarnings = new Set([
    'MISSING_AUTHOR',
    'MISSING_YEAR',
    'MISSING_TITLE',
    'LOW_CONFIDENCE_METADATA',
    'SUSPICIOUS_AUTHOR_METADATA',
    'TITLE_FALLBACK_FILENAME'
  ]);
  if (meta.metadataReliable === false) return false;
  if (!authors.length || !year || !title) return false;
  if (suspiciousAuthor(meta.authorDisplay ?? meta.author ?? authors[0])) return false;
  if (warnings.some(w => blockingWarnings.has(w))) return false;
  return true;
}

function inText(meta, label) {
  const authors = authorsOf(meta);
  const year = yearOf(meta);
  let names;

  if (authors.length === 1) {
    names = lastName(authors[0]);
  } else if (authors.length === 2) {
    names = lastName(authors[0]) + ' & ' + lastName(authors[1]);
  } else if (authors.length > 2) {
    names = lastName(authors[0]) + ' et al.';
  } else {
    // No authors — use a shortened title
    const t = safeTitle(meta) || label || 'Unknown';
    names = t.split(' ').slice(0, 3).join(' ');
  }

  const title = safeTitle(meta);
  const sortKey = (authors.length ? lastName(authors[0]) : (title || label || '')).toLowerCase();

  return { names, year, sortKey };
}

function sentenceCaseTitle(title) {
  const t = String(title ?? '').trim();
  if (!t) return '[Untitled source]';
  const isAllCaps = /^[^a-z]*$/.test(t);
  const parts = t.split(':');
  const casedParts = parts.map(part => {
    let text = part.trim();
    if (!text) return '';
    if (isAllCaps) text = text.toLowerCase();
    text = text.replace(/\b(ai|llm|api|nlp|rag|ui|ux|gpu|tpu|cpu|html|css|json|http|https|usa|uk)\b/gi, match => match.toUpperCase());
    return text.charAt(0).toUpperCase() + text.slice(1);
  });
  return casedParts.join(': ');
}

// ── Runtime data from previous nodes ────────────────────────────────────────
// The citation engine is fed by the validation/IF node (contains sections),
// but the source manifest lives in Prepare RAG Context1's output.
const item       = $input.first().json;
const validation = item.validation ?? {};
const sections   = item.sections   ?? {};

// Pull the source manifest from the RAG context node where it was built.
// Fall back through several possible locations for compatibility.
let ragCtx = {};
try { ragCtx = $('Prepare RAG Context1').first().json; } catch(e) {}

const manifest  =
  Array.isArray(item.manifest)           ? item.manifest           :
  Array.isArray(item.prep?.manifest)     ? item.prep.manifest      :
  Array.isArray(ragCtx.source_manifest)  ? ragCtx.source_manifest  :
  Array.isArray(ragCtx.manifest)         ? ragCtx.manifest         :
  [];

const sessionId = ragCtx.sessionId ?? item.sessionId ?? '';

const labelMap = {};
for (const src of manifest) {
  const meta = src.metadata ?? {};
  const cite = inText(meta, src.label);
  labelMap[String(src.label).toLowerCase()] = {
    label: src.label,
    names: cite.names,
    year: cite.year,
    inTextParenthetical: meta.citation ? meta.citation.inTextParenthetical : null,
    sortKey: cite.sortKey,
    reference: meta.citation && meta.citation.reference ? meta.citation.reference : referenceEntry(meta)
  };
}

const usedLabels = new Set();
const unknownPlaceholders = new Set();

function replacePlaceholders(text) {
  if (!text) return '';

  // 1. Find clusters of [DocX] that are adjacent (optionally separated by spaces or punctuation like commas)
  // We'll replace them all at once so we can sort them and merge them into a single parenthesis.
  const clusterRegex = /(?:\[\s*Doc\s*\d+\s*\](?:[,\s]*\[\s*Doc\s*\d+\s*\])*)/gi;

  return text.replace(clusterRegex, (clusterMatch) => {
    const docRegex = /\[\s*Doc\s*(\d+)\s*\]/gi;
    let match;
    const docs = [];
    while ((match = docRegex.exec(clusterMatch)) !== null) {
      const num = match[1];
      const key = ('doc' + num).toLowerCase();
      const c = labelMap[key];
      if (c) {
        usedLabels.add(c.label);
        docs.push(c);
      } else {
        unknownPlaceholders.add('Doc' + num);
      }
    }

    if (docs.length === 0) return clusterMatch;

    // Sort them alphabetically by sortKey (same as reference list)
    docs.sort((a, b) => a.sortKey.localeCompare(b.sortKey));

    // Format each one. inTextParenthetical includes the parentheses, e.g. "(Author, 2020)".
    // We need to strip the outer parentheses and join with semicolons.
    const innerTexts = docs.map(c => {
      const parenthetical = c.inTextParenthetical || '(' + c.names + ', ' + c.year + ')';
      // strip leading '(' and trailing ')'
      return parenthetical.replace(/^\(/, '').replace(/\)$/, '');
    });

    return '(' + innerTexts.join('; ') + ')';
  });
}

function tidy(text) {
  return String(text)
    .replace(/\s+([.,;:])/g, '$1')
    .replace(/\(\s+/g, '(')
    .replace(/\s+\)/g, ')')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/ +\n/g, '\n')
    .replace(/\s+\./g, '.')
    .trim();
}

const background = tidy(replacePlaceholders(sections.background || ''));
const rationale  = tidy(replacePlaceholders(sections.rationale  || ''));
const gap        = tidy(replacePlaceholders(sections.gap        || ''));

if (unknownPlaceholders.size > 0) {
  return [{
    json: {
      success: false,
      status: 'VALIDATION_FAILED',
      validationStatus: 'FAILED',
      message: 'Draft generation stopped because the AI used source placeholders that are not in the usable approved source manifest.',
      errorMessage: 'Unresolved placeholders: ' + Array.from(unknownPlaceholders).join(', '),
      validationFlags: ['UNRESOLVED_SOURCE_PLACEHOLDER'],
      unsupportedClaimFlags: validation.unsupportedClaimFlags ?? [],
      metrics: validation.metrics ?? {},
      retryRecommended: true,
      meta: {
        unresolvedPlaceholders: Array.from(unknownPlaceholders),
        sourceManifest: manifest.map(s => ({ label: s.label, sourceTier: s.sourceTier, requiredForCoverage: s.requiredForCoverage })),
        excludedSources: ragCtx.excluded_sources ?? []
      }
    }
  }];
}

const parts = [];
if (background) parts.push('Background\n\n' + background);
if (rationale)  parts.push('Rationale\n\n'  + rationale);
if (gap)        parts.push('Research Gap\n\n' + gap);

const contentText = parts.join('\n\n');
if (!contentText) throw new Error('Citation engine produced no draft content.');

const references = manifest
  .filter(src => usedLabels.has(src.label))
  .map(src => labelMap[String(src.label).toLowerCase()])
  .sort((a, b) => a.sortKey.localeCompare(b.sortKey))
  .map(c => c.reference);

const referencesText = references.join('\n');

const sourcesAvailable = manifest.length;
const requiredSources = manifest.filter(s => s.requiredForCoverage === true);
const requiredSourceLabels = new Set((requiredSources.length ? requiredSources : manifest).map(s => String(s.label)));
const sourcesCited = usedLabels.size;
const requiredSourcesCited = [...usedLabels].filter(label => requiredSourceLabels.has(label)).length;
const sourceCoverage = sourcesAvailable ? sourcesCited / sourcesAvailable : 0;
const requiredSourceCoverage = requiredSourceLabels.size ? requiredSourcesCited / requiredSourceLabels.size : 0;

return [{
  json: {
    draftId: uuid(),
    sessionId,
    contentText,
    referencesText,
    sections: { background, rationale, gap },
    references,
    citationsUsed: Array.from(usedLabels).sort(),
    validationStatus: 'PASSED',
    validationFlags: validation.validationFlags ?? [],
    unsupportedClaimFlags: validation.unsupportedClaimFlags ?? [],
    metrics: {
      ...(validation.metrics ?? {}),
      sourcesAvailable,
      sourcesCited,
      requiredSourcesAvailable: requiredSourceLabels.size,
      requiredSourcesCited,
      sourceCoverage,
      sourceCoveragePercent: Math.round(sourceCoverage * 100),
      requiredSourceCoverage,
      requiredSourceCoveragePercent: Math.round(requiredSourceCoverage * 100),
      formattingErrorRate: 0.0,
      placeholderValidationPassed: (unknownPlaceholders.size === 0),
      citationMetadataValidationPassed: true
    },
    createdAt: new Date().toISOString(),
